<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {ShieldCheck,Settings,Power,ScanLine,ListFilter,ChartNoAxesColumn,Activity,ChevronDown,RotateCw,AlertCircle,Shield,SlidersHorizontal,EyeOff,MessageSquare} from 'lucide-vue-next';
import {web,api,loadPrefs,tr,version,modeName,protectionModes,navigate,snapshot,num} from './api';
const tab=ref<any>(null),host=ref(''),level=ref(0),global=ref(0),count=ref<number|null>(null),lists=ref(0),busy=ref(true),error=ref(''),more=ref(false),forbid=ref<string[]>([]),autoReload=ref(true),last=ref(2);
const valid=computed(()=>Boolean(host.value)),active=computed(()=>valid.value&&level.value>0&&global.value>0),disabled=computed(()=>busy.value||!valid.value||global.value===0||forbid.value.includes('filteringMode'));
const quick=computed(()=>[{label:tr('Ẩn phần tử','Block element'),icon:ScanLine,action:()=>pick('picker'),disabled:!active.value||forbid.value.includes('picker')},{label:tr('Bộ lọc','Filters'),icon:ListFilter,action:()=>go('filters'),disabled:forbid.value.includes('dashboard')},{label:tr('Thống kê','Statistics'),icon:ChartNoAxesColumn,action:()=>go('overview'),disabled:forbid.value.includes('dashboard')},{label:tr('Nhật ký','Log'),icon:Activity,action:()=>go('activity'),disabled:!valid.value||forbid.value.includes('dashboard')}]);
async function init(){busy.value=true;error.value='';try{await loadPrefs();[tab.value]=await web.tabs.query({active:true,currentWindow:true});const u=new URL(tab.value?.url||'about:blank');if(/^https?:$/.test(u.protocol))host.value=u.hostname;const [g,ls]=await Promise.all([api('getDefaultFilteringMode'),api('getEnabledRulesets')]);global.value=g;lists.value=ls?.length||0;if(valid.value){const p=await api('popupPanelData',{origin:u.origin,hostname:host.value});if(!p)throw Error(tr('Không kết nối được engine','Engine unavailable'));level.value=p.level;autoReload.value=p.autoReload;forbid.value=p.disabledFeatures||[];last.value=level.value||g||2;try{const s=await web.storage.session.get('origin.lastSiteMode');if(s['origin.lastSiteMode']?.hostname===host.value)last.value=s['origin.lastSiteMode'].level;}catch{}try{const b=await web.action.getBadgeText({tabId:tab.value.id});if(/^\d+$/.test(b)){count.value=Number(b);await api('originObserve',{count:count.value,tabId:tab.value.id});}}catch{}if(count.value===null){try{const m=await web.declarativeNetRequest.getMatchedRules({tabId:tab.value.id});count.value=m.rulesMatchedInfo?.length||0;}catch{}}}}catch(e:any){error.value=e.message||String(e);}finally{busy.value=false;}}
async function change(n:number){if(disabled.value||n===level.value)return;busy.value=true;error.value='';const old=level.value;try{if(n>1&&!await web.permissions.contains({origins:['*://*.'+host.value+'/*']})){if(!await web.permissions.request({origins:['*://*.'+host.value+'/*']}))throw Error(tr('Chưa cấp quyền website','Site permission not granted'));}const actual=await api<number>('setFilteringMode',{hostname:host.value,level:n});if(actual!==n)throw Error(tr('Không thể đổi mức bảo vệ','Could not change protection'));level.value=actual;if(n===0&&old>0){last.value=old;await web.storage.session.set({'origin.lastSiteMode':{hostname:host.value,level:old}});}if(n>0)last.value=n;if(autoReload.value)await web.tabs.reload(tab.value.id);}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function go(p:string){try{if(p==='activity'&&valid.value)await snapshot(tab.value.id,host.value);await navigate(p);window.close();}catch(e:any){error.value=e.message;}}
async function pick(kind:string){if(!active.value)return;const files=kind==='zapper'?['/js/scripting/tool-overlay.js','/js/scripting/zapper.js']:['/js/scripting/css-procedural-api.js','/js/scripting/tool-overlay.js','/js/scripting/'+kind+'.js'];try{await web.scripting.executeScript({files,target:{tabId:tab.value.id}});window.close();}catch(e:any){error.value=e.message;}}
async function report(){await web.tabs.create({url:'https://github.com/lowji194/Origin-uBlock/issues/new'});window.close();}
onMounted(init);
</script>
<template>
<main class="popup-shell">
 <header class="popup-header"><div class="brand"><span class="brand-mark"><ShieldCheck :size="25" :stroke-width="2.1"/></span><div><b>Origin uBlock</b><small>{{tr('Chặn quảng cáo & bảo mật','Ad blocking & privacy')}}</small></div></div><button class="icon-button" :title="tr('Cài đặt','Settings')" @click="go('settings')" :disabled="forbid.includes('dashboard')"><Settings :size="21"/></button></header>
 <div v-if="error" class="notice danger"><AlertCircle :size="16"/>{{error}}<button @click="init"><RotateCw :size="15"/></button></div>
 <section class="popup-hero" :class="{paused:!active}">
   <div class="power-halo" :class="{active}"><button class="power-button" :aria-pressed="active" :aria-label="tr('Bật/tắt bảo vệ','Toggle protection')" :disabled="disabled" @click="change(active?0:last)"><Power :size="43" :stroke-width="2.5"/></button></div>
   <h1>{{busy?tr('Đang kết nối…','Connecting…'):!valid?tr('Trang không hỗ trợ','Unsupported page'):active?tr('Bạn đang được bảo vệ','You are protected'):tr('Bảo vệ đang tạm dừng','Protection is paused')}}</h1>
   <div class="host"><span class="status-dot" :class="{active}"></span>{{host||tr('Trang nội bộ trình duyệt','Browser internal page')}}</div>
   <p v-if="global===0" class="small">{{tr('Bật bảo vệ toàn cục trong cài đặt.','Resume global protection in settings.')}}</p>
 </section>
 <div class="popup-metrics"><article><Shield :size="17"/><strong>{{count===null?'—':num(count)}}</strong><span>{{tr('Lượt lọc trên tab','Filter actions on tab')}}</span></article><article><SlidersHorizontal :size="17"/><strong>{{num(lists)}}</strong><span>{{tr('Bộ lọc hoạt động','Active filter lists')}}</span></article></div>
 <div class="level-head"><span>{{tr('Mức độ bảo vệ','Protection level')}}</span><span class="small">{{modeName(level)}}</span></div>
 <div class="segmented"><button v-for="m in protectionModes" :key="m.id" :class="{selected:level===m.id&&active}" :disabled="disabled" :title="m.desc" @click="change(m.id)">{{m.name}}</button></div>
 <nav class="quick-nav"><button v-for="item in quick" :key="item.label" :disabled="item.disabled" @click="item.action"><component :is="item.icon" :size="20" :stroke-width="1.8"/><span>{{item.label}}</span></button></nav>
 <button class="more-button" @click="more=!more">{{tr('Công cụ khác','More tools')}}<ChevronDown :size="15" :class="{rotated:more}"/></button>
 <div v-if="more" class="more-tools"><button :disabled="!active||forbid.includes('zapper')" @click="pick('zapper')"><EyeOff :size="16"/>{{tr('Ẩn tạm thời','Temporarily hide')}}</button><button :disabled="!active||forbid.includes('picker')" @click="pick('unpicker')"><ScanLine :size="16"/>{{tr('Khôi phục phần tử','Unhide elements')}}</button><button @click="report"><MessageSquare :size="16"/>{{tr('Báo lỗi','Report issue')}}</button></div>
 <footer>v{{version}} <span>·</span> {{tr('Không gửi dữ liệu duyệt web','No browsing telemetry')}}</footer>
</main>
</template>
